    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(row):
        out = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            out.append((start, c - 1))
        return out

    # Detect a sequence of shrinking foreground runs, separated by one
    # background cell. Continue it with single-cell marks spaced three apart.
    desc_marks = {}
    for r, row in enumerate(grid):
        rr = runs(row)
        if len(rr) >= 3:
            lens = [b - a + 1 for a, b in rr]
            gaps = [rr[i + 1][0] - rr[i][1] - 1
                    for i in range(len(rr) - 1)]
            if (all(lens[i] > lens[i + 1] for i in range(len(lens) - 1))
                    and all(g == 1 for g in gaps)
                    and rr[-1][1] < w - 1
                    and all(x == bg for x in row[rr[-1][1] + 1:])):
                marks = []
                c = rr[-1][1] + 2
                while c < w:
                    marks.append(c)
                    c += 3
                desc_marks[r] = marks

    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        rr = runs(row)
        if not rr:
            continue
        last = rr[-1][1]
        if last == w - 1:
            continue

        # Periodic alternating continuation when the row contains a clear
        # alternating stretch and its foreground pattern ends at the boundary.
        alternating = False
        for s in range(w):
            for length in range(5, min(9, w - s) + 1):
                if s + length - 1 > last:
                    break
                seq = row[s:s + length]
                if all(seq[i] != seq[i - 1] for i in range(1, length)):
                    alternating = True
                    break
            if alternating:
                break

        if alternating:
            for c in range(last + 1, w):
                if (c - last) % 2 == 0:
                    out[r][c] = 1
            continue

        # A neighboring row can encode the continuation of a long solid bar.
        if r + 1 in desc_marks and rr[0][0] == 0 and len(rr) == 1:
            for c in desc_marks[r + 1]:
                if c > last:
                    out[r][c] = 1
            continue

        lengths = [b - a + 1 for a, b in rr]
        if lengths[-1] == max(lengths) and lengths[-1] >= 3:
            for c in range(last + 1, w):
                out[r][c] = 1

        if r in desc_marks:
            for c in desc_marks[r]:
                out[r][c] = 1

    return out
